import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Sidebar from '../components/layout/Sidebar';
import { startMockTest, submitMockTest, getMockTestHistory } from '../services/api';

const TEST_TYPES = [
  { type: 'APTITUDE', icon: '🧮', title: 'Aptitude Test', desc: 'Quantitative, logical & verbal questions', color: '#2563eb' },
  { type: 'PROGRAMMING', icon: '💻', title: 'Programming Test', desc: 'Coding & DSA questions', color: '#7c3aed' },
  { type: 'MIXED', icon: '🎯', title: 'Mixed Test', desc: 'Aptitude + Programming combined', color: '#f59e0b' },
];

export default function MockTests() {
  const navigate = useNavigate();
  const [phase, setPhase] = useState('select'); // select, test, result
  const [testData, setTestData] = useState(null);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answered, setAnswered] = useState({});
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [selectedType, setSelectedType] = useState('');

  useEffect(() => {
    getMockTestHistory().then(r => setHistory(r.data)).catch(console.error);
  }, []);

  const handleStartTest = async (testType) => {
    setSelectedType(testType);
    try {
      const res = await startMockTest(testType);
      setTestData(res.data);
      setCurrentIdx(0);
      setAnswered({});
      setPhase('test');
    } catch (err) { console.error(err); }
  };

  const handleAnswer = (questionId, option) => {
    if (answered[questionId]) return;
    setAnswered(prev => ({ ...prev, [questionId]: option }));
  };

  const handleFinish = async () => {
    const questions = testData.questions || [];
    let correct = 0;
    questions.forEach(q => {
      if (answered[q.id] === q.correctAnswer) correct++;
    });
    try {
      const res = await submitMockTest({ testType: selectedType, totalQuestions: questions.length, correctAnswers: correct });
      setResult({ ...res.data, correctAnswers: correct, totalQuestions: questions.length });
      setPhase('result');
      getMockTestHistory().then(r => setHistory(r.data));
    } catch (err) { console.error(err); }
  };

  const OPTIONS = ['A','B','C','D'];
  const OPT_MAP = { A: 'optionA', B: 'optionB', C: 'optionC', D: 'optionD' };

  return (
    <div className="app-layout">
      <Sidebar />
      <div className="main-content fade-in">
        <div className="page-header">
          <button className="back-btn" onClick={() => { navigate('/dashboard'); }}>← Back</button>
          <div><h1>📝 Mock Tests</h1><p style={{color:'var(--mid)',fontSize:'0.9rem'}}>Simulate real interview conditions</p></div>
        </div>

        {phase === 'select' && (
          <>
            <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(280px,1fr))',gap:'1.25rem',marginBottom:'2rem'}}>
              {TEST_TYPES.map(t => (
                <div className="mock-test-card" key={t.type} onClick={() => handleStartTest(t.type)}>
                  <div className="test-icon">{t.icon}</div>
                  <h3 style={{fontFamily:'var(--font-display)',fontSize:'1.2rem',fontWeight:'700',marginBottom:'0.5rem'}}>{t.title}</h3>
                  <p style={{color:'var(--mid)',fontSize:'0.9rem',marginBottom:'1.5rem'}}>{t.desc}</p>
                  <button className="btn btn-primary" style={{background:t.color}}>Start Test →</button>
                </div>
              ))}
            </div>

            {history.length > 0 && (
              <div className="card">
                <div className="card-header"><span className="card-title">📊 Test History</span></div>
                <table style={{width:'100%',borderCollapse:'collapse',fontSize:'0.9rem'}}>
                  <thead>
                    <tr style={{borderBottom:'2px solid var(--border)'}}>
                      {['Test Type','Score','Correct','Total','Date'].map(h=><th key={h} style={{padding:'0.75rem',textAlign:'left',fontSize:'0.8rem',color:'var(--mid)',fontWeight:'700',textTransform:'uppercase'}}>{h}</th>)}
                    </tr>
                  </thead>
                  <tbody>
                    {history.map(h => (
                      <tr key={h.id} style={{borderBottom:'1px solid var(--border)'}}>
                        <td style={{padding:'0.75rem',fontWeight:'600'}}>{h.testType}</td>
                        <td style={{padding:'0.75rem'}}>
                          <span style={{color: h.scorePercentage >= 75 ? 'var(--success)' : h.scorePercentage >= 50 ? 'var(--accent)' : 'var(--danger)',fontWeight:'700'}}>
                            {h.scorePercentage}%
                          </span>
                        </td>
                        <td style={{padding:'0.75rem',color:'var(--success)',fontWeight:'600'}}>{h.correctAnswers}</td>
                        <td style={{padding:'0.75rem'}}>{h.totalQuestions}</td>
                        <td style={{padding:'0.75rem',color:'var(--mid)'}}>{new Date(h.takenAt).toLocaleDateString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}

        {phase === 'test' && testData && (
          <div className="question-page" style={{maxWidth:'800px',margin:'0 auto'}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:'1.25rem'}}>
              <span style={{fontFamily:'var(--font-display)',fontWeight:'700',fontSize:'1rem'}}>
                {selectedType} Test — {Object.keys(answered).length}/{testData.questions?.length} answered
              </span>
              <button className="btn btn-primary" onClick={handleFinish}>
                ✅ Submit Test
              </button>
            </div>
            {testData.questions?.map((q, idx) => (
              <div className="question-card" key={q.id}>
                <div className="question-meta">
                  <span className="q-counter">Q{idx+1}</span>
                  <span className={`difficulty-badge diff-${q.difficulty?.toLowerCase()}`}>{q.difficulty}</span>
                </div>
                <div className="question-text">{q.questionText}</div>
                <div className="options-grid">
                  {OPTIONS.map(opt => {
                    const text = q[OPT_MAP[opt]];
                    if (!text) return null;
                    const sel = answered[q.id] === opt;
                    return (
                      <button key={opt} className={`option-btn${sel?' selected':''}`}
                        onClick={() => handleAnswer(q.id, opt)}>
                        <span className="option-label">{opt}</span>
                        <span>{text}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            ))}
            <button className="btn btn-primary btn-lg" style={{width:'100%',justifyContent:'center'}} onClick={handleFinish}>
              ✅ Submit & See Results
            </button>
          </div>
        )}

        {phase === 'result' && result && (
          <div className="results-card fade-in-up">
            <h2 style={{fontFamily:'var(--font-display)',fontSize:'1.5rem',fontWeight:'800'}}>Test Complete! 🎉</h2>
            <div className="score-circle">{Math.round(result.scorePercentage)}%</div>
            <div style={{display:'flex',gap:'2rem',justifyContent:'center',marginBottom:'1.5rem'}}>
              <div style={{textAlign:'center'}}>
                <div style={{fontSize:'1.5rem',fontWeight:'800',color:'var(--success)'}}>{result.correctAnswers}</div>
                <div style={{fontSize:'0.82rem',color:'var(--mid)'}}>Correct</div>
              </div>
              <div style={{textAlign:'center'}}>
                <div style={{fontSize:'1.5rem',fontWeight:'800',color:'var(--danger)'}}>{result.totalQuestions - result.correctAnswers}</div>
                <div style={{fontSize:'0.82rem',color:'var(--mid)'}}>Wrong</div>
              </div>
              <div style={{textAlign:'center'}}>
                <div style={{fontSize:'1.5rem',fontWeight:'800'}}>{result.totalQuestions}</div>
                <div style={{fontSize:'0.82rem',color:'var(--mid)'}}>Total</div>
              </div>
            </div>
            <p style={{color:'var(--mid)',marginBottom:'1.5rem',fontSize:'0.95rem'}}>
              {result.scorePercentage >= 75 ? '🌟 Excellent performance!' : result.scorePercentage >= 50 ? '👍 Good effort! Keep practicing.' : '📚 Keep studying. You can do it!'}
            </p>
            <div style={{display:'flex',gap:'1rem',justifyContent:'center',flexWrap:'wrap'}}>
              <button className="btn btn-primary" onClick={() => setPhase('select')}>Try Another Test</button>
              <button className="btn btn-outline" onClick={() => navigate('/dashboard')}>Go to Dashboard</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
